#!/usr/bin/env bash
# D8 step 7c: extend the v4 feature set to the chain snapshots regenerated by scripts/d8_chain_replay.py.
# Same extractor, same --out as step 2 (scripts/d8_extract_features.sh); the extractor's resume identity check
# refuses to run if anything in the extraction identity changed, and entries that already have features are skipped,
# so only the newly installed entries are extracted. The staging zoo is rebuilt so the new entries appear in it.
set -euo pipefail
CODE="$(cd "$(dirname "$0")/.." && pwd)"
PY=/home/ubuntu/projects/wsp-lab/.venv/bin/python
DATA=/home/ubuntu/wsp-data
Z=$DATA/zoo/qwen3.5-0.8b
ST=$DATA/runs/d8/staging_zoo
OUT=$DATA/features/qwen3.5-0.8b
[ -e "$OUT/manifest.json" ] || { echo "$OUT has no manifest; run scripts/d8_extract_features.sh first" >&2; exit 1; }
$PY - "$Z" "$ST" <<'PYE'
import json, sys
from pathlib import Path
Z, ST = Path(sys.argv[1]), Path(sys.argv[2])
ST.mkdir(parents=True, exist_ok=True)
added = 0
for line in (Z / "artefact_status.jsonl").read_text().splitlines():
    r = json.loads(line)
    d = ST / r["id"]
    if r["delta_present"]:
        if d.is_symlink() and d.resolve() == (Z / r["id"]).resolve():
            continue
        if d.is_dir() and not d.is_symlink():  # was an alias stub; the entry now has its own bytes
            for child in d.iterdir():
                child.unlink()
            d.rmdir()
        if not d.exists():
            d.symlink_to(Z / r["id"]); added += 1
    elif r["alias_of"]:
        d.mkdir(exist_ok=True)
        if not (d / "edit.json").is_symlink(): (d / "edit.json").symlink_to(Z / r["id"] / "edit.json")
        t = Z / r["alias_of"]
        if (t / "delta.safetensors").exists():
            if not (d / "delta.safetensors").is_symlink(): (d / "delta.safetensors").symlink_to(t / "delta.safetensors")
        else:
            if not (d / "lora").is_symlink(): (d / "lora").symlink_to(t / "lora")
if not (ST / "manifest.jsonl").is_symlink():
    (ST / "manifest.jsonl").symlink_to(Z / "manifest.jsonl")
print("staging entries:", sum(1 for p in ST.iterdir() if p.name != "manifest.jsonl"), "added:", added)
PYE
cd "$CODE"
export PYTHONPATH="$CODE/src" TOKENIZERS_PARALLELISM=false OMP_NUM_THREADS=1 MKL_NUM_THREADS=1
unset HF_HOME
git rev-parse HEAD
date -u +"start %FT%TZ"
$PY -m wsp.features.extract --zoo "$ST" --out "$OUT" --workers "${WORKERS:-4}"
date -u +"end %FT%TZ"
